def verify(witness):
    n = witness['n']
    pts = [(int(p[0]), int(p[1])) for p in witness['points']]
    if len(pts) != n:
        raise ValueError('point count mismatch')
    if len(set(pts)) != n:
        raise ValueError('repeated point')
    d = [(pts[i+1][0]-pts[i][0], pts[i+1][1]-pts[i][1]) for i in range(n-1)]
    if any(x != d[0] for x in d):
        raise ValueError('not an arithmetic progression')
    if d[0] == (0, 0):
        raise ValueError('degenerate AP')
    for i in range(n):
        if (pts[i][0]-pts[0][0])*d[0][1] != (pts[i][1]-pts[0][1])*d[0][0]:
            raise ValueError('off line')
    def sq_dist(a, b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2
    R = []
    for i in range(n):
        ds = set()
        for j in range(n):
            if j != i:
                ds.add(sq_dist(pts[i], pts[j]))
        R.append(len(ds))
    for r in R:
        if not (1 <= r <= n-1):
            raise ValueError('pigeonhole violated')
    if len(set(R)) > n - 1:
        raise ValueError('too many distinct R values')
    for i in range(n):
        if R[i] != max(i, n-1-i):
            raise ValueError('AP distance profile wrong')
    if len(set(R)) != (n + 1) // 2:
        raise ValueError('distinct count != ceil(n/2)')
